#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DataType {
    ScalarInt,
    ScalarFloat,
    ScalarComplex,
    ScalarBool,
    ScalarString,
    ArrayType,
    CompositeType,
    UnknownType,
}

pub fn issctype(rep: DataType) -> bool {
    matches!(
        rep,
        DataType::ScalarInt
            | DataType::ScalarFloat
            | DataType::ScalarComplex
            | DataType::ScalarBool
            | DataType::ScalarString
    )
}

